const SUPABASE_URL="https://dphiuepbsullrscuuzrc.supabase.co",KEY="sb_publishable_kmj9VR5ie5sFFQvGm9TcSw_MbBGUMtq";
const client=window.lookalikeSupabaseClient||window.supabase.createClient(SUPABASE_URL,KEY),page=document.body.dataset.page;
const $=s=>document.querySelector(s),esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const category={human:"인물",character:"애니 캐릭터",animal:"동물"},status={pending:"검토 중",approved:"공개됨",changes:"수정 요청",rejected:"반려됨",hidden:"숨김"};
let session=null,profile=null,draft=JSON.parse(sessionStorage.getItem("lookalike-share-draft")||"null"),draftImage=null,draftUrl=null;
function toast(message){const el=$("#toast");if(!el)return;el.textContent=message;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2600)}
function openDb(){return new Promise((resolve,reject)=>{const r=indexedDB.open("lookalike-community",1);r.onupgradeneeded=()=>r.result.createObjectStore("drafts");r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function getDraftImage(){const db=await openDb();return new Promise((resolve,reject)=>{const r=db.transaction("drafts").objectStore("drafts").get("latest-image");r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)})}
async function clearDraft(){sessionStorage.removeItem("lookalike-share-draft");draft=null;draftImage=null;if(draftUrl)URL.revokeObjectURL(draftUrl);draftUrl=null;try{const db=await openDb();db.transaction("drafts","readwrite").objectStore("drafts").delete("latest-image")}catch{}}
async function loadProfile(){if(!session)return profile=null;const{data}=await client.from("profiles").select("nickname").eq("user_id",session.user.id).single();profile=data||null;document.querySelectorAll("[data-account-label]").forEach(el=>el.textContent=profile?.nickname||"내 계정")}
async function login(){const{error}=await client.auth.signInWithOAuth({provider:"google",options:{redirectTo:`${location.origin}${location.pathname}`}});if(error)toast("Google 로그인을 시작하지 못했습니다.")}
async function signedImage(path){if(!path)return null;const{data}=await client.storage.from("community-posts").createSignedUrl(path,3600);return data?.signedUrl||null}
function postHtml(post){return `<article class="post-card ${post.image_url?"has-photo":""}">${post.image_url?`<img class="post-photo" src="${post.image_url}" alt="${esc(post.profiles?.nickname||"사용자")}가 공개한 사진" loading="lazy">`:""}<div class="post-result"><small>${category[post.result_category]||"결과"} · <span class="score">${post.result_score}%</span></small><b>${esc(post.result_name)}</b></div><p class="post-message">${esc(post.message)}</p><div class="post-side"><div class="post-author"><b>${esc(post.profiles?.nickname||"익명")}</b><time>${new Intl.DateTimeFormat("ko",{month:"short",day:"numeric"}).format(new Date(post.approved_at))}</time></div><button class="like-button ${post.liked?"liked":""}" data-like="${post.id}" type="button" aria-pressed="${post.liked}" aria-label="${post.liked?"좋아요 취소":"좋아요"}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.4 4.7 13.5A4.8 4.8 0 0 1 11.5 6.7L12 7.2l.5-.5a4.8 4.8 0 0 1 6.8 6.8Z"/></svg><span>${post.likes_count||0}</span></button></div></article>`}
async function toggleLike(button,post){if(!session){toast("로그인하면 좋아요를 누를 수 있어요.");setTimeout(()=>location.href="/account",700);return}button.disabled=true;const wasLiked=post.liked;post.liked=!wasLiked;post.likes_count=Math.max(0,(post.likes_count||0)+(wasLiked?-1:1));button.classList.toggle("liked",post.liked);button.setAttribute("aria-pressed",String(post.liked));button.setAttribute("aria-label",post.liked?"좋아요 취소":"좋아요");button.querySelector("span").textContent=post.likes_count;const query=wasLiked?client.from("post_likes").delete().eq("post_id",post.id).eq("user_id",session.user.id):client.from("post_likes").insert({post_id:post.id,user_id:session.user.id}),{error}=await query;if(error){post.liked=wasLiked;post.likes_count=Math.max(0,post.likes_count+(wasLiked?1:-1));button.classList.toggle("liked",post.liked);button.setAttribute("aria-pressed",String(post.liked));button.querySelector("span").textContent=post.likes_count;toast("좋아요를 반영하지 못했습니다.")}button.disabled=false}
async function loadFeed(){const root=$("#feed");root.innerHTML='<div class="loading-box">결과를 불러오는 중</div>';const{data,error}=await client.from("posts").select("id,result_name,result_category,result_score,message,image_path,approved_at,likes_count,profiles!posts_user_id_fkey(nickname)").eq("status","approved").order("approved_at",{ascending:false}).limit(50);if(error){console.error("feed query failed",error);return root.innerHTML='<div class="empty-box">피드를 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.</div>'}if(!data.length)return root.innerHTML='<div class="empty-box">아직 공개된 결과가 없습니다.</div>';let liked=new Set;if(session){const{data:likes}=await client.from("post_likes").select("post_id").eq("user_id",session.user.id).in("post_id",data.map(p=>p.id));liked=new Set((likes||[]).map(x=>x.post_id))}const posts=await Promise.all(data.map(async p=>({...p,liked:liked.has(p.id),image_url:await signedImage(p.image_path)})));root.innerHTML=posts.map(postHtml).join("");root.querySelectorAll("[data-like]").forEach(button=>{const post=posts.find(p=>p.id===button.dataset.like);button.onclick=()=>toggleLike(button,post)})}
async function imageForUpload(blob){const bitmap=await createImageBitmap(blob),scale=Math.min(1,1280/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement("canvas");canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext("2d").drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return new Promise(resolve=>canvas.toBlob(resolve,"image/jpeg",.82))}
function renderShare(){const root=$("#shareRoot");if(!session){root.innerHTML='<div class="state-card"><div><strong>로그인 후 결과 피드에 공유할 수 있어요.</strong><p>Google 계정으로 로그인하면 이 화면으로 다시 돌아옵니다.</p></div><button class="primary-button" type="button">Google로 로그인</button></div>';root.querySelector("button").onclick=login;return}if(!draft){root.innerHTML='<div class="state-card"><div><strong>아직 공유할 검사 결과가 없어요.</strong><p>닮은꼴 검사 결과 화면에서 ‘결과 피드에 공유’를 눌러 이곳으로 보내주세요.</p></div><a class="secondary-button" style="display:grid;place-items:center;text-decoration:none" href="/">닮은꼴 찾기</a></div>';return}root.innerHTML=`<div class="draft"><div class="draft-result"><div><small>${category[draft.category]||"결과"}</small><b>${esc(draft.name)}</b></div><strong>${draft.score}%</strong></div><form class="draft-form"><label for="message">결과에 덧붙일 한마디</label><div class="message-wrap"><textarea id="message" maxlength="80" placeholder="결과를 본 첫 느낌을 짧게 남겨주세요." required></textarea><span><b>0</b>/80</span></div>${draftUrl?`<label class="photo-option"><input type="checkbox" id="includePhoto"><img src="${draftUrl}" alt="이번 검사 사진 미리보기"><span><b>내 사진도 함께 공개</b><small>직접 선택한 경우에만 게시물용으로 저장됩니다.</small></span></label>`:""}<div class="actions"><button class="cancel" type="button">취소</button><button class="submit" type="submit">검토 요청</button></div></form></div>`;const form=root.querySelector("form"),textarea=form.querySelector("textarea");textarea.oninput=()=>form.querySelector(".message-wrap b").textContent=textarea.value.length;form.querySelector(".cancel").onclick=async()=>{await clearDraft();renderShare()};form.onsubmit=submitPost}
async function submitPost(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector(".submit"),include=Boolean(form.querySelector("#includePhoto")?.checked&&draftImage);button.disabled=true;button.textContent="제출 중";const{data:post,error}=await client.from("posts").insert({user_id:session.user.id,result_name:draft.name,result_category:draft.category,result_score:draft.score,message:form.querySelector("textarea").value.trim()}).select("id").single();if(error){button.disabled=false;button.textContent="검토 요청";return toast("게시물을 제출하지 못했습니다.")}if(include){const path=`${session.user.id}/${post.id}.jpg`,image=await imageForUpload(draftImage),{error:uploadError}=await client.storage.from("community-posts").upload(path,image,{contentType:"image/jpeg",upsert:false});if(uploadError){await client.from("posts").delete().eq("id",post.id);button.disabled=false;button.textContent="검토 요청";return toast("사진 업로드에 실패했습니다.")}const{error:updateError}=await client.from("posts").update({image_path:path}).eq("id",post.id);if(updateError){await client.storage.from("community-posts").remove([path]);await client.from("posts").delete().eq("id",post.id);return toast("사진 연결에 실패했습니다.")}}await clearDraft();$("#shareRoot").innerHTML='<div class="state-card"><div><strong>검토 요청을 보냈습니다.</strong><p>관리자가 승인하면 결과 피드에 공개됩니다. 진행 상태는 내 계정에서 확인하세요.</p></div><a class="primary-button" style="display:grid;place-items:center;text-decoration:none" href="/account">내 공유 내역 보기</a></div>';toast("검토 요청을 보냈습니다.")}
async function deletePost(post){if(!confirm("이 공유 결과를 삭제할까요?"))return;if(post.image_path){const{error}=await client.storage.from("community-posts").remove([post.image_path]);if(error)return toast("사진을 삭제하지 못했습니다.")}const{error}=await client.from("posts").delete().eq("id",post.id);if(error)return toast("공유 결과를 삭제하지 못했습니다.");toast("삭제했습니다.");renderAccount()}
async function renderAccount(){const root=$("#accountRoot");if(!session){root.innerHTML='<div class="state-card"><div><strong>내 계정에 로그인하세요.</strong><p>Google 계정으로 로그인해 닉네임과 공유 결과의 검토 상태를 관리할 수 있습니다.</p></div><button class="primary-button" type="button">Google로 로그인</button></div>';root.querySelector("button").onclick=login;return}root.innerHTML=`<div class="account-grid"><section class="account-panel"><h2>프로필</h2><div class="account-email">${esc(session.user.email)}</div><form class="nickname-form"><label for="nickname">공개 닉네임</label><input id="nickname" value="${esc(profile?.nickname||"")}" minlength="2" maxlength="16" required><button type="submit">닉네임 저장</button></form><button class="logout" type="button">로그아웃</button></section><section class="account-panel"><h2>내 공유 내역</h2><div class="history" id="history"><div class="loading-box">공유 내역을 불러오는 중</div></div></section></div>`;root.querySelector(".nickname-form").onsubmit=async e=>{e.preventDefault();const nickname=root.querySelector("#nickname").value.trim(),{error}=await client.from("profiles").update({nickname,updated_at:new Date().toISOString()}).eq("user_id",session.user.id);if(error)return toast(error.code==="23505"?"이미 사용 중인 닉네임입니다.":"닉네임을 저장하지 못했습니다.");profile.nickname=nickname;document.querySelectorAll("[data-account-label]").forEach(el=>el.textContent=nickname);toast("닉네임을 변경했습니다.")};root.querySelector(".logout").onclick=async()=>{await client.auth.signOut();session=null;profile=null;document.querySelectorAll("[data-account-label]").forEach(el=>el.textContent="로그인");renderAccount()};const{data,error}=await client.from("posts").select("id,result_name,status,image_path,moderation_note,created_at").eq("user_id",session.user.id).order("created_at",{ascending:false}).limit(30);const history=$("#history");if(error)return history.innerHTML='<div class="empty-box">공유 내역을 불러오지 못했습니다.</div>';if(!data.length)return history.innerHTML='<div class="empty-box">아직 보낸 결과가 없습니다.</div>';history.innerHTML=data.map(p=>`<div class="history-item"><div><b>${esc(p.result_name)}</b><small>${status[p.status]||p.status}${p.moderation_note?` · ${esc(p.moderation_note)}`:""}</small></div><button data-id="${p.id}" type="button">삭제</button></div>`).join("");history.querySelectorAll("[data-id]").forEach(btn=>btn.onclick=()=>deletePost(data.find(p=>p.id===btn.dataset.id)))}
async function init(){const[{data}]=await Promise.all([client.auth.getSession(),page==="share"?(async()=>{if(draft&&(!draft.createdAt||Date.now()-draft.createdAt>3600000))await clearDraft();if(draft?.hasImage)try{draftImage=await getDraftImage();if(draftImage)draftUrl=URL.createObjectURL(draftImage)}catch{}})():Promise.resolve()]);session=data.session;if(session)await loadProfile();if(page==="feed"){$("#refreshFeed").onclick=loadFeed;await loadFeed()}if(page==="share")renderShare();if(page==="account")await renderAccount()}
client.auth.onAuthStateChange((_event,next)=>setTimeout(async()=>{session=next;if(session)await loadProfile();if(page==="share")renderShare();if(page==="account")renderAccount()},0));init();
